# Harness for queue.c - test enqueue/dequeue operations with symbolic inputs
cat > harness_queue.c << 'HARNESS'
#include <r_util.h>
#include <klee/klee.h>

int main() {
    // Symbolic initial capacity
    int capacity;
    klee_make_symbolic(&capacity, sizeof(capacity), "capacity");

    // Constrain to reasonable range
    klee_assume(capacity >= 1 && capacity <= 16);

    RQueue *q = r_queue_new(capacity);
    if (!q) {
        klee_assert(0); // Should not happen for valid capacity
        return 1;
    }

    // Enqueue some elements
    int vals[4];
    klee_make_symbolic(vals, sizeof(vals), "vals");

    for (int i = 0; i < 4; i++) {
        r_queue_enqueue(q, (void*)(long)(vals[i] + 1)); // avoid NULL
    }

    // Dequeue and verify FIFO ordering
    for (int i = 0; i < 4; i++) {
        void *el = r_queue_dequeue(q);
        if (el == NULL && i < capacity) {
            // Should not be empty if we haven't exceeded capacity
            klee_assert(0);
        }
    }

    r_queue_free(q);
    return 0;
}
HARNESS
echo "harness_queue.c created"

# Harness for stack.c
cat > harness_stack.c << 'HARNESS'
#include <r_util.h>
#include <klee/klee.h>

int main() {
    int n;
    klee_make_symbolic(&n, sizeof(n), "n");
    klee_assume(n >= 1 && n <= 16);

    RStack *s = r_stack_new(n);
    if (!s) {
        klee_assert(0);
        return 1;
    }

    int vals[4];
    klee_make_symbolic(vals, sizeof(vals), "vals");

    for (int i = 0; i < 4; i++) {
        bool res = r_stack_push(s, (void*)(long)(vals[i] + 1));
        if (!res && i < n) {
            klee_assert(0); // Push should succeed within capacity
        }
    }

    // Pop and verify LIFO ordering
    for (int i = 0; i < 4; i++) {
        void *el = r_stack_pop(s);
        if (el == NULL && i < n) {
            klee_assert(0);
        }
    }

    r_stack_free(s);
    return 0;
}
HARNESS
echo "harness_stack.c created"

