# Harness for debruijn.c
cat > harness_debruijn.c << 'HARNESS'
#include <r_util.h>
#include <klee/klee.h>
#include <string.h>

int main() {
    int size;
    klee_make_symbolic(&size, sizeof(size), "size");
    klee_assume(size >= 1 && size <= 64);

    int start;
    klee_make_symbolic(&start, sizeof(start), "start");
    klee_assume(start >= 0 && start < size);

    char *pattern = r_debruijn_pattern(size, start, NULL);
    if (pattern) {
        size_t len = strlen(pattern);
        klee_assert(len <= (size_t)size);
        free(pattern);
    }

    // Test offset function
    ut64 value;
    klee_make_symbolic(&value, sizeof(value), "value");
    int offset = r_debruijn_offset(value, false);
    klee_assert(offset >= -1);

    return 0;
}
