# Create harness for base32
cat > harness_base32.c << 'HARNESS'
#include <r_util.h>
#include <klee/klee.h>
#include <string.h>

int main() {
    // Test base32_encode_ut64 / base32_decode_ut64 roundtrip
    ut64 input;
    klee_make_symbolic(&input, sizeof(input), "input");

    char *encoded = base32_encode_ut64(input);
    if (encoded) {
        ut64 decoded = base32_decode_ut64(encoded);
        // The roundtrip may not be exact due to 65-bit vs 64-bit
        // but encoding should always produce valid base32 chars
        for (int i = 0; i < 13; i++) {
            char c = encoded[i];
            klee_assert((c >= 'A' && c <= 'Z') || (c >= '2' && c <= '7'));
        }
        free(encoded);
    }

    // Test r_base32_decode with symbolic input
    char sym_input[8];
    klee_make_symbolic(sym_input, sizeof(sym_input), "sym_input");
    size_t out_len;
    ut8 *decoded = r_base32_decode(sym_input, 8, &out_len);
    if (decoded) {
        klee_assert(out_len == 5);
        free(decoded);
    }

    return 0;
}
HARNESS
echo "harness_base32.c created"

# Create harness for bitmap
cat > harness_bitmap.c << 'HARNESS'
#include <r_util.h>
#include <klee/klee.h>

int main() {
    size_t len;
    klee_make_symbolic(&len, sizeof(len), "len");
    klee_assume(len >= 1 && len <= 64);

    RBitmap *b = r_bitmap_new(len);
    if (!b) {
        return 1;
    }

    // Symbolic bit positions
    size_t bit1, bit2;
    klee_make_symbolic(&bit1, sizeof(bit1), "bit1");
    klee_make_symbolic(&bit2, sizeof(bit2), "bit2");
    klee_assume(bit1 < len);
    klee_assume(bit2 < len);

    r_bitmap_set(b, bit1);
    if (!r_bitmap_test(b, bit1)) {
        klee_assert(0); // Set bit should be testable
    }

    r_bitmap_unset(b, bit1);
    if (r_bitmap_test(b, bit1)) {
        klee_assert(0); // Unset bit should not test true
    }

    r_bitmap_set(b, bit2);
    size_t count = r_bitmap_count(b);
    klee_assert(count >= 1);

    r_bitmap_free(b);
    return 0;
}
HARNESS
echo "harness_bitmap.c created"

