# Create a getopt harness for option parsing analysis
cat > harness_getopt.c << 'HARNESS'
#include <r_util.h>
#include <klee/klee.h>
#include <string.h>

int main() {
    // Symbolic command-line arguments
    char arg0[] = "program";
    char arg1[16];
    char arg2[16];
    char arg3[16];

    klee_make_symbolic(arg1, sizeof(arg1), "arg1");
    klee_make_symbolic(arg2, sizeof(arg2), "arg2");
    klee_make_symbolic(arg3, sizeof(arg3), "arg3");

    // Null terminate
    arg1[15] = 0;
    arg2[15] = 0;
    arg3[15] = 0;

    // Make args start with '-' to exercise option parsing
    klee_assume(arg1[0] == '-');
    klee_assume(arg1[1] != 0); // at least one char after dash
    klee_assume(arg1[1] != '-'); // not "--"

    const char *argv[] = { arg0, arg1, arg2, arg3, NULL };
    int argc = 4;

    const char *ostr = "ab:c:d";
    RGetopt opt;
    r_getopt_init(&opt, argc, argv, ostr);

    int c;
    int count = 0;
    while ((c = r_getopt_next(&opt)) != -1) {
        count++;
        if (count > 10) break; // Safety limit
    }

    return 0;
}
