/* radare - LGPL - Copyright 2024 - pancake */

#include <r_util.h>
#include <r_util/r_base32.h>

static const char base32_alphabet[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
static const char base32_padding = '=';

// Utility function to find index in base32 alphabet
static int base32_char_index(char c) {
	if (c >= 'A' && c <= 'Z') {
		return c - 'A';
	}
	if (c >= '2' && c <= '7') {
		return c - '2' + 26;
	}
	return -1;
}

R_API char *r_base32_encode(const ut8 *data, size_t input_length, size_t *output_length) {
	const size_t encoded_size = (input_length + 4) / 5 * 8;
	char *encoded_data = (char *)malloc (encoded_size + 1);
	if (!encoded_data) {
		return NULL;
	}

	size_t i, j, index;
	int current_byte, next_byte;
	for (i = 0, j = 0; i < input_length;) {
		current_byte = data[i++] << 8;
		if (i < input_length) current_byte |= data[i++];
		current_byte <<= 8;
		if (i < input_length) current_byte |= data[i++];
		current_byte <<= 8;
		if (i < input_length) current_byte |= data[i++];
		current_byte <<= 8;
		if (i < input_length) current_byte |= data[i++];

		for (index = 0; index < 8; index++) {
			next_byte = (current_byte & 0xF8000000) >> 27;
			encoded_data[j++] = base32_alphabet[next_byte];
			current_byte <<= 5;
		}
	}

	while (j < encoded_size) {
		encoded_data[j++] = base32_padding;
	}
	encoded_data[encoded_size] = '\0';

	if (output_length) {
		*output_length = encoded_size;
	}
	return encoded_data;
}

R_API ut8 *r_base32_decode(const char *data, size_t input_length, size_t *output_length) {
	if (input_length % 8 != 0) {
		return NULL;
	}

	size_t decoded_size = input_length * 5 / 8;
	unsigned char *decoded_data = (unsigned char *)malloc (decoded_size);
	if (!decoded_data) {
		return NULL;
	}

	size_t i, j, index;
	int current_byte, next_byte;
	for (i = 0, j = 0; i < input_length;) {
		current_byte = 0;
		for (index = 0; index < 8 && i < input_length; index++) {
			next_byte = base32_char_index (toupper (data[i++]));
			if (next_byte == -1) {
				free (decoded_data);
				return NULL;
			}
			current_byte = (current_byte << 5) | next_byte;
		}

		for (index = 0; index < 5; index++) {
			decoded_data[j++] = (current_byte & 0xFF000000) >> 24;
			current_byte <<= 8;
		}
	}

	if (output_length) {
		*output_length = decoded_size;
	}
	return decoded_data;
}

R_API char *base32_encode_ut64(ut64 input) {
	size_t encoded_size = 13; // Maximum 13 characters for 64-bit input
	char *encoded_data = (char *)malloc (encoded_size + 1);
	if (!encoded_data) {
		return NULL;
	}

	int i;
	for (i = 12; i >= 0; i--) {
		encoded_data[i] = base32_alphabet[input & 0x1F];
		input >>= 5;
	}
	encoded_data[encoded_size] = '\0';

	return encoded_data;
}

// Decode function for ut64
R_API ut64 base32_decode_ut64(const char *input) {
	ut64 decoded_value = 0;
	int i;
	for (i = 0; i < 13; i++) {
		int index = base32_char_index (toupper (input[i]));
		if (index == -1) {
			return 0;
		}
		decoded_value = (decoded_value << 5) | index;
	}
	return decoded_value;
}

/* radare - LGPL - Copyright 2026 - pancake */

#ifndef R_BITS_H
#define R_BITS_H

#include <r_types.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Centralized portable bit helpers. Use these instead of __builtin_*
 * directly so non-GCC/clang toolchains (MSVC, TCC) keep working. */

#if defined(__GNUC__) || defined(__clang__)
#define R_HAVE_BUILTIN_BITS 1
#else
#define R_HAVE_BUILTIN_BITS 0
#endif

static inline int r_bits_popcount32(ut32 x) {
#if R_HAVE_BUILTIN_BITS
	return __builtin_popcount (x);
#else
	x = x - ((x >> 1) & 0x55555555U);
	x = (x & 0x33333333U) + ((x >> 2) & 0x33333333U);
	return (int)((((x + (x >> 4)) & 0x0F0F0F0FU) * 0x01010101U) >> 24);
#endif
}

static inline int r_bits_popcount64(ut64 x) {
#if R_HAVE_BUILTIN_BITS
	return __builtin_popcountll ((unsigned long long)x);
#else
	x = x - ((x >> 1) & 0x5555555555555555ULL);
	x = (x & 0x3333333333333333ULL) + ((x >> 2) & 0x3333333333333333ULL);
	x = (x + (x >> 4)) & 0x0F0F0F0F0F0F0F0FULL;
	return (int)((x * 0x0101010101010101ULL) >> 56);
#endif
}

/* count trailing zeros: returns 32/64 when x is 0 (matching R bit-width) */
static inline int r_bits_ctz32(ut32 x) {
#if R_HAVE_BUILTIN_BITS
	return x ? __builtin_ctz (x) : 32;
#else
	int n = 0;
	if (!x) {
		return 32;
	}
	if (!(x & 0x0000FFFFU)) { n += 16; x >>= 16; }
	if (!(x & 0x000000FFU)) { n += 8;  x >>= 8; }
	if (!(x & 0x0000000FU)) { n += 4;  x >>= 4; }
	if (!(x & 0x00000003U)) { n += 2;  x >>= 2; }
	if (!(x & 0x00000001U)) { n += 1; }
	return n;
#endif
}

static inline int r_bits_ctz64(ut64 x) {
#if R_HAVE_BUILTIN_BITS
	return x ? __builtin_ctzll ((unsigned long long)x) : 64;
#else
	int n = 0;
	if (!x) {
		return 64;
	}
	if (!(x & 0xFFFFFFFFULL)) { n += 32; x >>= 32; }
	if (!(x & 0x0000FFFFULL)) { n += 16; x >>= 16; }
	if (!(x & 0x000000FFULL)) { n += 8;  x >>= 8; }
	if (!(x & 0x0000000FULL)) { n += 4;  x >>= 4; }
	if (!(x & 0x00000003ULL)) { n += 2;  x >>= 2; }
	if (!(x & 0x00000001ULL)) { n += 1; }
	return n;
#endif
}

/* count leading zeros: returns 32/64 when x is 0 */
static inline int r_bits_clz32(ut32 x) {
#if R_HAVE_BUILTIN_BITS
	return x ? __builtin_clz (x) : 32;
#else
	int n = 0;
	if (!x) {
		return 32;
	}
	if (!(x & 0xFFFF0000U)) { n += 16; x <<= 16; }
	if (!(x & 0xFF000000U)) { n += 8;  x <<= 8; }
	if (!(x & 0xF0000000U)) { n += 4;  x <<= 4; }
	if (!(x & 0xC0000000U)) { n += 2;  x <<= 2; }
	if (!(x & 0x80000000U)) { n += 1; }
	return n;
#endif
}

static inline int r_bits_clz64(ut64 x) {
#if R_HAVE_BUILTIN_BITS
	return x ? __builtin_clzll ((unsigned long long)x) : 64;
#else
	int n = 0;
	if (!x) {
		return 64;
	}
	if (!(x & 0xFFFFFFFF00000000ULL)) { n += 32; x <<= 32; }
	if (!(x & 0xFFFF000000000000ULL)) { n += 16; x <<= 16; }
	if (!(x & 0xFF00000000000000ULL)) { n += 8;  x <<= 8; }
	if (!(x & 0xF000000000000000ULL)) { n += 4;  x <<= 4; }
	if (!(x & 0xC000000000000000ULL)) { n += 2;  x <<= 2; }
	if (!(x & 0x8000000000000000ULL)) { n += 1; }
	return n;
#endif
}

#ifdef __cplusplus
}
#endif

#endif //  R_BITS_H
