tool_calls.command:
cd /workspace/klee_harnesses

# Fix the randomart harness - add r_print.h include
cat > harness_randomart.c << 'HARNESS'
#include <r_util.h>
#include <r_util/r_print.h>
#include <klee/klee.h>
#include <string.h>

int main() {
    ut8 dgst[16];
    klee_make_symbolic(dgst, sizeof(dgst), "dgst");

    ut64 addr;
    klee_make_symbolic(&addr, sizeof(addr), "addr");

    char *result = r_print_randomart(dgst, 16, addr);
    if (result) {
        klee_assert(result[0] == '+');
        free(result);
    }

    return 0;
}
HARNESS

clang -emit-llvm -c -g -O0 -Xclang -disable-O0-optnone \
  -I /workspace/radare2/libr/include \
  -I /workspace/radare2/subprojects/sdb/include \
  -I /workspace/klee/include \
  harness_randomart.c -o harness_randomart.bc 2>&1 | head -10

echo "=== Linking ==="
llvm-link harness_randomart.bc randomart.bc -o linked_randomart.bc 2>&1
ls -la linked_randomart.bc
